import{_ as e,c as i,a as o,o as t}from"./index-DCEC8k-Z.js";const r={class:"min-h-screen bg-gray-50 py-12 px-4 sm:px-6 lg:px-8"},s={__name:"TermsView",setup(b){return(l,a)=>(t(),i("div",r,[...a[0]||(a[0]=[o('<div class="max-w-4xl mx-auto bg-white shadow-xl rounded-3xl overflow-hidden" data-v-24bb6b40><div class="bg-white px-8 py-10 border-b border-gray-100" data-v-24bb6b40><h1 class="text-3xl md:text-4xl font-black text-gray-900 border-b-4 border-black pb-4 uppercase tracking-tighter" data-v-24bb6b40> TÉRMINOS Y CONDICIONES GENERALES DE USO — eOrder </h1><p class="mt-4 text-gray-500 font-medium" data-v-24bb6b40>Última actualización: 16 de mayo de 2026</p></div><div class="px-8 py-10 text-gray-700 leading-relaxed space-y-8 text-sm md:text-base" data-v-24bb6b40><p data-v-24bb6b40> El presente documento regula el acceso, uso, contratación y operación de la plataforma SaaS denominada <strong data-v-24bb6b40>eOrder (Easy Order)</strong>, propiedad y operada por <strong data-v-24bb6b40>Merag Comercial / Materiales, Tecnología y Automatización / Food Software Services Mexico / eOrder Mexico</strong>, en adelante “eOrder”, con domicilio fiscal en Trapiche 96, El Cortijo, Veracruz, Veracruz, México, RFC MCO2404269V5. </p><p data-v-24bb6b40>Al acceder, registrarse, contratar o utilizar cualquier servicio relacionado con eOrder, el usuario acepta plenamente los presentes términos y condiciones, el aviso de privacidad, políticas complementarias y cualquier documento legal relacionado.</p><div class="bg-yellow-50 border-l-8 border-yellow-400 p-5 rounded-r-xl font-bold text-yellow-900" data-v-24bb6b40> Si el usuario no está de acuerdo con cualquiera de las disposiciones aquí establecidas, deberá abstenerse de utilizar la plataforma. </div><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>1. DEFINICIONES</h2><ul class="list-disc pl-6 space-y-2" data-v-24bb6b40><li data-v-24bb6b40><strong data-v-24bb6b40>Plataforma:</strong> sistema SaaS eOrder.</li><li data-v-24bb6b40><strong data-v-24bb6b40>Usuario:</strong> cualquier persona física o moral con acceso autorizado.</li><li data-v-24bb6b40><strong data-v-24bb6b40>Cliente:</strong> negocio, restaurante o empresa que contrata el servicio.</li><li data-v-24bb6b40><strong data-v-24bb6b40>Subusuario:</strong> empleado o colaborador autorizado por el cliente.</li><li data-v-24bb6b40><strong data-v-24bb6b40>Servicios:</strong> funcionalidades digitales ofrecidas por eOrder.</li><li data-v-24bb6b40><strong data-v-24bb6b40>SaaS:</strong> software como servicio basado en nube.</li></ul></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>2. SERVICIOS OFRECIDOS</h2><p data-v-24bb6b40>eOrder proporciona una plataforma tecnológica enfocada al sector restaurantero y de alimentos, incluyendo de manera enunciativa más no limitativa:</p><ul class="list-disc pl-6 mt-4 grid grid-cols-1 md:grid-cols-2 gap-2" data-v-24bb6b40><li data-v-24bb6b40>Sistema POS.</li><li data-v-24bb6b40>Comandas digitales.</li><li data-v-24bb6b40>KDS / Cocina digital.</li><li data-v-24bb6b40>Control de inventario.</li><li data-v-24bb6b40>Módulos de delivery.</li><li data-v-24bb6b40>Analítica y métricas.</li><li data-v-24bb6b40>Herramientas de inteligencia artificial.</li><li data-v-24bb6b40>Aplicaciones móviles.</li><li data-v-24bb6b40>Administración multisucursal.</li><li data-v-24bb6b40>Marketplace e integraciones.</li><li data-v-24bb6b40>Integraciones con servicios de terceros.</li><li data-v-24bb6b40>Automatización de procesos.</li><li data-v-24bb6b40>Bots y automatizaciones por WhatsApp.</li></ul><p class="mt-4" data-v-24bb6b40>La plataforma opera principalmente bajo infraestructura en nube y puede depender parcial o totalmente de servicios de terceros para su funcionamiento.</p></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>3. REGISTRO Y CUENTAS</h2><ul class="list-disc pl-6 space-y-2" data-v-24bb6b40><li data-v-24bb6b40>La edad mínima para contratar el servicio es de 18 años.</li><li data-v-24bb6b40>El usuario es responsable de mantener la confidencialidad de sus credenciales.</li><li data-v-24bb6b40>El cliente podrá crear subusuarios internos bajo su propia responsabilidad.</li><li data-v-24bb6b40>Las cuentas son personales e intransferibles.</li><li data-v-24bb6b40>eOrder podrá suspender, limitar o cancelar cuentas por uso indebido, fraude, spam, actividades ilícitas o afectaciones a la plataforma.</li><li data-v-24bb6b40>El acceso compartido no autorizado podrá generar suspensión inmediata.</li></ul></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>4. PLANES, PAGOS Y FACTURACIÓN</h2><ul class="list-disc pl-6 space-y-2" data-v-24bb6b40><li data-v-24bb6b40>Los servicios podrán contratarse bajo modalidad mensual o anual.</li><li data-v-24bb6b40>eOrder ofrece un periodo de prueba gratuito de 30 días.</li><li data-v-24bb6b40>No existe permanencia mínima obligatoria.</li><li data-v-24bb6b40>La renovación de los servicios podrá realizarse automáticamente en la fecha de vencimiento.</li><li data-v-24bb6b40>Los pagos actualmente son procesados mediante MercadoPago Developer y métodos compatibles.</li><li data-v-24bb6b40>La factura será emitida automáticamente una vez confirmado el pago.</li><li data-v-24bb6b40>La falta de pago podrá ocasionar suspensión parcial o total del servicio.</li><li data-v-24bb6b40>No existen reembolsos monetarios, salvo ajustes internos de saldo derivados exclusivamente de caídas atribuibles a proveedores externos de hosting o infraestructura.</li><li data-v-24bb6b40>eOrder podrá modificar precios hasta dos veces por año conforme a inflación, costos operativos o ajustes tecnológicos.</li></ul></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>5. POLÍTICA DE CANCELACIÓN</h2><ul class="list-disc pl-6 space-y-2" data-v-24bb6b40><li data-v-24bb6b40>El cliente podrá cancelar el servicio desde la plataforma mediante el botón correspondiente.</li><li data-v-24bb6b40>Una vez cancelada la cuenta, los datos podrán eliminarse inmediatamente.</li><li data-v-24bb6b40>eOrder no garantiza recuperación posterior de información eliminada.</li><li data-v-24bb6b40>Las cuentas inactivas por más de 3 meses podrán eliminarse automáticamente.</li></ul></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>6. USO ACEPTABLE</h2><p data-v-24bb6b40>Queda estrictamente prohibido:</p><ul class="list-disc pl-6 space-y-2" data-v-24bb6b40><li data-v-24bb6b40>Intentar vulnerar la seguridad de la plataforma.</li><li data-v-24bb6b40>Realizar ingeniería inversa.</li><li data-v-24bb6b40>Copiar, revender o sublicenciar el software.</li><li data-v-24bb6b40>Utilizar bots maliciosos.</li><li data-v-24bb6b40>Realizar spam.</li><li data-v-24bb6b40>Usar la plataforma para actividades ilícitas.</li><li data-v-24bb6b40>Interferir con otros usuarios.</li><li data-v-24bb6b40>Intentar acceder a información no autorizada.</li><li data-v-24bb6b40>Manipular métricas o procesos internos.</li></ul><p class="mt-4" data-v-24bb6b40>eOrder podrá suspender inmediatamente cualquier cuenta que represente riesgo operativo, técnico, legal o reputacional.</p></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>7. LIMITACIÓN DE RESPONSABILIDAD</h2><p data-v-24bb6b40>eOrder no será responsable por daños directos, indirectos, incidentales, especiales o consecuenciales derivados de:</p><ul class="list-disc pl-6 space-y-2 grid grid-cols-1 md:grid-cols-2" data-v-24bb6b40><li data-v-24bb6b40>Caídas de internet.</li><li data-v-24bb6b40>Fallos de proveedores externos.</li><li data-v-24bb6b40>Pérdida de ventas.</li><li data-v-24bb6b40>Errores del usuario.</li><li data-v-24bb6b40>Uso indebido por empleados.</li><li data-v-24bb6b40>Fallos eléctricos.</li><li data-v-24bb6b40>Hackeos.</li><li data-v-24bb6b40>Malware.</li><li data-v-24bb6b40>Errores de hardware externo.</li><li data-v-24bb6b40>Problemas con impresoras.</li><li data-v-24bb6b40>Integraciones externas.</li><li data-v-24bb6b40>Fallas de APIs de terceros.</li><li data-v-24bb6b40>Suspensiones de servicios externos.</li><li data-v-24bb6b40>Interrupciones por mantenimiento.</li><li data-v-24bb6b40>Casos fortuitos o fuerza mayor.</li></ul><p class="mt-4" data-v-24bb6b40>El usuario reconoce que ningún sistema digital es completamente inmune a fallos, vulnerabilidades o interrupciones.</p><p data-v-24bb6b40>La responsabilidad total acumulada de eOrder nunca excederá el monto efectivamente pagado por el cliente durante los últimos 30 días previos al evento reclamado.</p></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>8. PROPIEDAD INTELECTUAL</h2><ul class="list-disc pl-6 space-y-2" data-v-24bb6b40><li data-v-24bb6b40>Todo el software, diseño, código, estructura, algoritmos, funcionalidades, interfaces y tecnología de eOrder son propiedad exclusiva de eOrder y sus entidades relacionadas.</li><li data-v-24bb6b40>El cliente conserva propiedad sobre sus datos operativos.</li><li data-v-24bb6b40>Se prohíbe copiar, descompilar, modificar, distribuir o revender el software.</li><li data-v-24bb6b40>El uso de la plataforma no transfiere derechos de propiedad intelectual.</li></ul></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>9. PRIVACIDAD Y DATOS PERSONALES</h2><p data-v-24bb6b40>eOrder podrá recopilar y procesar:</p><ul class="list-disc pl-6 space-y-2 mb-4" data-v-24bb6b40><li data-v-24bb6b40>Datos de clientes finales.</li><li data-v-24bb6b40>Ventas.</li><li data-v-24bb6b40>Métodos de pago.</li><li data-v-24bb6b40>Ubicación.</li><li data-v-24bb6b40>Correos electrónicos.</li><li data-v-24bb6b40>WhatsApp y datos de contacto.</li><li data-v-24bb6b40>Información operativa y estadística.</li></ul><p data-v-24bb6b40>El usuario acepta que parte de la información podrá utilizarse para:</p><ul class="list-disc pl-6 space-y-2 mt-2" data-v-24bb6b40><li data-v-24bb6b40>Analítica, Mejoras de servicio, Entrenamiento de modelos internos, Automatizaciones, Inteligencia artificial, Desarrollo de nuevas funcionalidades.</li></ul><p class="mt-4" data-v-24bb6b40>La información podrá compartirse con empresas relacionadas, plataformas afiliadas o desarrollos pertenecientes al mismo grupo tecnológico, aun cuando operen bajo razones sociales distintas.</p><p data-v-24bb6b40>eOrder declara implementar medidas razonables de seguridad conforme a la Ley Federal de Protección de Datos Personales en Posesión de los Particulares y principios generales compatibles con GDPR.</p></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>10. POLÍTICA DE COOKIES</h2><p data-v-24bb6b40>La plataforma podrá utilizar cookies, identificadores de sesión, almacenamiento local y tecnologías similares para:</p><ul class="list-disc pl-6 space-y-2 mt-2" data-v-24bb6b40><li data-v-24bb6b40>Autenticación, Seguridad, Analítica, Mejora de experiencia, Preferencias del usuario, Rendimiento de la plataforma.</li></ul><p class="mt-4" data-v-24bb6b40>El usuario podrá deshabilitar cookies desde su navegador, aunque algunas funcionalidades podrían verse limitadas.</p></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>11. INTELIGENCIA ARTIFICIAL Y AUTOMATIZACIONES</h2><ul class="list-disc pl-6 space-y-2" data-v-24bb6b40><li data-v-24bb6b40>La IA podrá sugerir promociones dentro de la aplicación.</li><li data-v-24bb6b40>Los bots podrán solicitar información para canalizar incidencias.</li><li data-v-24bb6b40>Los sistemas automatizados no sustituyen asesoría profesional.</li><li data-v-24bb6b40>eOrder no garantiza exactitud absoluta de recomendaciones automatizadas.</li><li data-v-24bb6b40>El usuario acepta que cualquier decisión comercial basada en IA es bajo su propio riesgo.</li><li data-v-24bb6b40>eOrder no será responsable por decisiones tomadas fuera del modelo implementado oficialmente.</li></ul></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>12. SOPORTE TÉCNICO</h2><ul class="list-disc pl-6 space-y-2" data-v-24bb6b40><li data-v-24bb6b40>Horario: 08:00 a 20:00 horas.</li><li data-v-24bb6b40>Canal principal: WhatsApp.</li><li data-v-24bb6b40>Tiempo promedio de respuesta: 1 hora.</li><li data-v-24bb6b40>El soporte en línea está incluido sin costo adicional.</li><li data-v-24bb6b40>El onboarding inicial no tiene costo.</li><li data-v-24bb6b40>Los tiempos de solución podrán variar según complejidad, terceros involucrados y disponibilidad técnica.</li></ul></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>13. SLA Y DISPONIBILIDAD</h2><p data-v-24bb6b40>eOrder realizará esfuerzos comercialmente razonables para mantener la disponibilidad del servicio. No obstante:</p><ul class="list-disc pl-6 space-y-2 mt-2" data-v-24bb6b40><li data-v-24bb6b40>No se garantiza disponibilidad ininterrumpida.</li><li data-v-24bb6b40>Podrán existir mantenimientos programados.</li><li data-v-24bb6b40>Dependencias externas pueden afectar la operación.</li><li data-v-24bb6b40>Los servicios cloud son operados parcialmente por terceros.</li></ul></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>14. INTEGRACIONES Y APIs</h2><p data-v-24bb6b40>Las integraciones con servicios externos podrán cambiar, limitarse o descontinuarse sin previo aviso. eOrder no controla políticas, estabilidad ni disponibilidad de plataformas externas. El usuario asume riesgos derivados del uso de integraciones de terceros.</p></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>15. MARKETPLACE Y PLUGINS</h2><p data-v-24bb6b40>Los complementos, plugins o herramientas externas podrán ser operados por terceros independientes. eOrder no garantiza compatibilidad permanente ni funcionamiento continuo de desarrollos externos.</p></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>16. POLÍTICA ANTI FRAUDE</h2><p data-v-24bb6b40>eOrder podrá monitorear actividad sospechosa, intentos de fraude, accesos anómalos, automatización maliciosa y cualquier actividad que comprometa la integridad de la plataforma. Las cuentas sospechosas podrán limitarse o bloquearse preventivamente.</p></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>17. CONSENTIMIENTO WHATSAPP</h2><p data-v-24bb6b40>El usuario autoriza expresamente el envío de comunicaciones operativas, técnicas, administrativas y de soporte mediante WhatsApp. Los bots automatizados podrán participar en procesos iniciales de soporte y clasificación de incidencias.</p></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>18. FUERZA MAYOR</h2><p data-v-24bb6b40>eOrder no será responsable por incumplimientos derivados de eventos fuera de su control razonable, incluyendo: Desastres naturales, fallas masivas de internet, apagones, conflictos laborales, ciberataques globales, actos gubernamentales, problemas de proveedores externos.</p></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>19. LEGISLACIÓN Y JURISDICCIÓN</h2><p data-v-24bb6b40>Los presentes términos se regirán conforme a las leyes federales de los Estados Unidos Mexicanos y legislación aplicable del Estado de Veracruz. Cualquier controversia será sometida a los tribunales competentes de Veracruz / Boca del Río, Veracruz, México. Las partes renuncian expresamente a cualquier otro fuero que pudiera corresponderles.</p></section><section data-v-24bb6b40><h2 class="text-2xl font-bold text-black border-l-4 border-black pl-4 mb-4 uppercase" data-v-24bb6b40>20. MODIFICACIONES</h2><p data-v-24bb6b40>eOrder podrá modificar estos términos en cualquier momento. Las modificaciones entrarán en vigor una vez publicadas dentro de la plataforma o sitio oficial. El uso continuo del servicio implica aceptación de las modificaciones.</p></section><section class="bg-gray-50 p-6 rounded-2xl border border-gray-100" data-v-24bb6b40><h2 class="text-2xl font-bold text-black mb-6 uppercase" data-v-24bb6b40>21. CONTACTO</h2><div class="grid grid-cols-1 md:grid-cols-2 gap-y-4 gap-x-8 text-sm" data-v-24bb6b40><p data-v-24bb6b40><strong data-v-24bb6b40>Razón social:</strong> Merag Comercial / Materiales, Tecnología y Automatización / Food Software Services Mexico / eOrder Mexico</p><p data-v-24bb6b40><strong data-v-24bb6b40>Nombre comercial:</strong> eOrder / Easy Order</p><p data-v-24bb6b40><strong data-v-24bb6b40>RFC:</strong> MCO2404269V5</p><p data-v-24bb6b40><strong data-v-24bb6b40>Domicilio:</strong> Trapiche 96, El Cortijo, Veracruz, Veracruz, México</p><p data-v-24bb6b40><strong data-v-24bb6b40>Correo legal:</strong> merag.comercial@gmail.com</p><p data-v-24bb6b40><strong data-v-24bb6b40>Correo soporte:</strong> soporte@corion.mx</p><p data-v-24bb6b40><strong data-v-24bb6b40>Teléfono:</strong> 2294848144</p><p data-v-24bb6b40><strong data-v-24bb6b40>Sitio web:</strong> https://www.corion.mx/cws/eorder/</p></div></section></div><div class="bg-gray-100 px-8 py-6 text-center text-gray-500 text-xs font-bold uppercase tracking-widest" data-v-24bb6b40> © 2026 eOrder — Todos los derechos reservados. </div></div>',1)])]))}},n=e(s,[["__scopeId","data-v-24bb6b40"]]);export{n as default};
